def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    s = str(num + 1)
    length = len(s)

    # If all 9's, the next palindrome is 10...01 (length+1 digits)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Otherwise, construct palindrome from left half and increment if needed
    half_len = length // 2
    odd = (length % 2 != 0)

    left = s[:half_len]
    middle = s[half_len] if odd else ''
    right = s[half_len+1:] if odd else s[half_len:]

    # Form palindrome by mirroring left + middle
    if odd:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) >= int(s):
        return int(palindrome)

    # Need to increment the middle part
    if odd:
        # Increment the middle digit and handle carry
        middle_num = int(middle)
        left_num = int(left) if left else 0

        # Increment middle digit
        middle_num += 1
        if middle_num == 10:
            # Middle digit overflows, increment left part
            middle_num = 0
            left_num += 1
            left = str(left_num).rjust(len(left), '0')
            palindrome = left + str(middle_num) + left[::-1]
        else:
            palindrome = left + str(middle_num) + left[::-1]
    else:
        # Even length: increment left part and mirror
        left_num = int(left) + 1
        left = str(left_num).rjust(len(left), '0')
        palindrome = left + left[::-1]

    return int(palindrome)

