def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length >= d:
        return 1
    jumps = math.ceil(d / length)
    # If exactly one jump can't reach and jumps=2 but distance is less than length*2, still 2 jumps suffice.
    # But if jumps > 2 and d is not an exact multiple of length, check if 2 jumps suffice (by triangle inequality)
    # Actually, if d <= length*2, 2 jumps suffice. Otherwise, jumps as computed.
    if jumps == 1:
        return 1
    if d <= 2 * length:
        return 2
    return jumps

