def will_it_fly(q, w):
    def balanced(weights, weight_limit):
        # If there's only one weight, it's balanced if sum <= weight_limit
        if len(weights) == 1:
            return weights[0] <= weight_limit

        total = sum(weights)
        if total > weight_limit:
            return False

        # Try all possible pivots
        for i in range(1, len(weights)):
            left = weights[:i]
            right = weights[i:]
            left_weight = sum(left)
            right_weight = sum(right)
            # Check the balancing rule: right_weight * length(left) == left_weight * length(right)
            if right_weight * len(left) == left_weight * len(right):
                # If balanced at pivot, recursively check sublists
                if balanced(left, weight_limit) and balanced(right, weight_limit):
                    return True
        return False

    return balanced(q, w)

def prime_length(string):
    n = len(string)
